function renderPlannerDetail(){let t=current(),box=$('#plannerDetail');if(page!=='plans'||!t){box.hidden=true;return}box.hidden=false;let ordered=t.plan?.[activeDay]||[];box.innerHTML=`<div class="detail-head"><div><span class="eyebrow">YOUR ITINERARY</span><h2>${esc(t.name)}</h2><p>${esc(t.destination)} · ${t.days} 天 · ${t.places.length} 个地点</p></div><div class="detail-head-actions"><button data-edit-trip="${esc(t.id)}" title="编辑旅行">✎</button><button data-plan-menu="${esc(t.id)}" title="管理计划">···</button></div></div><div class="detail-actions"><button id="importPlacesButton">⇧ 导入地点</button><button id="addPlaceButton">＋ 添加地点</button></div><div id="placeList">${t.places.length?t.places.map((p,i)=>`<div class="place-row"><span class="place-number">${i+1}</span><span class="place-text"><strong>${esc(p.name)}</strong><small>${validCoord(p)?esc(p.address||'已定位'):'待定位 · 点击可编辑坐标'}</small></span><button data-edit-place="${esc(p.id)}" title="编辑地点">✎</button><button data-delete-place="${esc(p.id)}" title="删除地点">×</button></div>`).join(''):`<div class="empty-box"><b>地点池是空的</b>上传截图或清单，也可以逐个添加地点。</div>`}</div><button class="primary-button" id="generateButton">✦ 生成更顺路的每日路线</button><p class="plan-help">仅对已定位地点分组和排序。规划后可调整每一天的站点顺序。</p><div id="routePanel">${t.plan?.some(x=>x.length)?`<div class="day-tabs">${Array.from({length:t.days},(_,i)=>`<button class="${i===activeDay?'active':''}" data-day="${i}">第 ${i+1} 天</button>`).join('')}</div><div class="route-summary">第 ${activeDay+1} 天 · ${ordered.length} 站 · 约 ${routeDistance(ordered).toFixed(1)} 公里直线距离</div>${ordered.map((p,i)=>`<div class="place-row"><span class="place-number">${i+1}</span><span class="place-text"><strong>${esc(p.name)}</strong><small>停留约 ${Number(p.duration)||90} 分钟 · ${esc(p.note||'查看地点')}</small></span><button data-move="${esc(p.id)}" data-dir="-1" title="上移">↑</button><button data-move="${esc(p.id)}" data-dir="1" title="下移">↓</button><button data-map-place="${esc(p.id)}" title="地图中查看">↗</button></div>`).join('')}`:''}</div>`}
function renderProfile(){let n=numbers();$('#profileCountries').textContent=n.countries;$('#profileCities').textContent=n.cities;$('#profileTrips').textContent=db.trips.length;$('#profileName').textContent=db.profile.name||'旅行收藏家';let avatar=db.profile.avatar;$('#profileAvatar').innerHTML=avatar?`<img src="${esc(avatar)}" alt="我的头像">`:'✦';$('#headerAvatarButton').innerHTML=avatar?`<img src="${esc(avatar)}" alt="我的头像">`:'◌'}
