let locationData=null,locationDataPromise=null;
function loadLocationData(){if(locationData)return Promise.resolve(locationData);if(!locationDataPromise)locationDataPromise=fetch('./assets/locations.json').then(r=>{if(!r.ok)throw Error('locations');return r.json()}).then(v=>locationData=v);return locationDataPromise}
const countryOptions=['中国','日本','韩国','泰国','新加坡','马来西亚','越南','法国','意大利','英国','美国','澳大利亚'];
const provinceOptions=['北京','天津','上海','重庆','河北','山西','辽宁','吉林','黑龙江','江苏','浙江','安徽','福建','江西','山东','河南','湖北','湖南','广东','海南','四川','贵州','云南','陕西','甘肃','青海','台湾','内蒙古','广西','西藏','宁夏','新疆','香港','澳门'];
const foreignCities={'日本':['东京','京都','大阪','奈良','札幌','冲绳','福冈'],'韩国':['首尔','釜山','济州'],'泰国':['曼谷','清迈','普吉'],'新加坡':['新加坡'],'马来西亚':['吉隆坡','槟城','沙巴'],'越南':['河内','岘港','胡志明市'],'法国':['巴黎','尼斯','里昂'],'意大利':['罗马','佛罗伦萨','威尼斯','米兰'],'英国':['伦敦','爱丁堡'],'美国':['纽约','洛杉矶','旧金山','芝加哥'],'澳大利亚':['悉尼','墨尔本'],'新西兰':['奥克兰','皇后镇']};
function geoProvinceName(value){return Object.keys(locationData?.provinces||{}).find(x=>cleanArea(x)===cleanArea(value))||''}
function citySuggestions(){let c=$('#tripForm')?.elements.country.value.trim()||'',p=geoProvinceName($('#tripForm')?.elements.province.value||'');if(c&&c!=='中国')return (foreignCities[c]||[]).map(name=>({name,province:'',country:c}));let provinces=locationData?.provinces||{};let result=[];for(let [province,cities] of Object.entries(provinces)){if(p&&province!==p)continue;if(/^(北京|天津|上海|重庆)市$/.test(province))result.push({name:province,province,country:'中国'});for(let name of cities)result.push({name,province,country:'中国'})}return result}
function setupLocationPicker(){
 let form=$('#tripForm'),city=form.elements.destination,country=form.elements.country,province=form.elements.province,box=$('#geoChoices'),timer,request=0,active='';
 function show(kind,remote=[]){active=kind;let input=kind==='city'?city:kind==='province'?province:country,q=input.value.trim().toLowerCase(),items=[];
 if(kind==='country')items=(locationData?.countries||countryOptions.map(name=>({name}))).map(x=>({name:x.name,sub:x.code||''}));
 else if(kind==='province')items=(locationData?Object.keys(locationData.provinces):provinceOptions).map(name=>({name,sub:''}));
 else items=citySuggestions().map(x=>({name:x.name,sub:cleanArea(x.province),province:x.province,country:x.country}));
 items=items.filter(x=>!q||[x.name,x.sub,x.name.replace(/市|地区|自治州|盟$/g,'')].some(v=>v?.toLowerCase().includes(q)));
 let count=items.length,visible=kind==='city'&&!q&&!province.value.trim()?items.slice(0,50):items;
 box.innerHTML=`<div class="geo-heading"><span>${kind==='city'?'选择城市 / 搜索全球地点':kind==='province'?'选择省 / 地区':'选择国家 / 地区'}</span><small>${locationData?`${count} 项 · 滑动查看`:'正在载入完整列表…'}</small></div><div class="geo-chips">${visible.map((x,i)=>`<button type="button" data-geo-index="${i}">${esc(x.name)}${kind==='city'&&x.sub?`<small>${esc(x.sub)}</small>`:''}</button>`).join('')}</div>${kind==='city'&&!q&&count>visible.length?`<p class="geo-more">先输入城市名，或先选省区查看全部 ${count} 项</p>`:''}${remote.length?`<div class="geo-remote">${remote.map((r,i)=>`<button type="button" data-geo-remote="${i}"><strong>${esc(r.name)}</strong><small>${esc([r.state,r.country].filter(Boolean).join(' · '))}</small></button>`).join('')}</div>`:''}${!count&&kind==='city'?'<p class="geo-more">没有匹配项，可直接输入城市名称；联网时会继续搜索。</p>':''}`;
 box.hidden=false;box.querySelectorAll('[data-geo-index]').forEach(b=>b.onclick=()=>{let x=visible[Number(b.dataset.geoIndex)];input.value=x.name;if(kind==='city'){if(x.province)province.value=cleanArea(x.province);if(x.country)country.value=x.country;delete form.dataset.cityLat;delete form.dataset.cityLon}else if(kind==='province'){country.value='中国';city.value=''}else{province.value='';city.value=''}box.hidden=true;if(kind==='province'){city.focus();show('city')}else if(kind==='country'&&country.value==='中国'){province.focus();show('province')}else if(kind==='country'){city.focus();show('city')}});
 box.querySelectorAll('[data-geo-remote]').forEach(b=>b.onclick=()=>{let r=remote[Number(b.dataset.geoRemote)];city.value=r.name;province.value=r.state||'';country.value=r.country||country.value;form.dataset.cityLat=r.lat;form.dataset.cityLon=r.lon;box.hidden=true})}
 for(let [kind,input] of [['city',city],['province',province],['country',country]]){input.addEventListener('focus',()=>show(kind));input.addEventListener('input',()=>{if(kind==='city'){delete form.dataset.cityLat;delete form.dataset.cityLon}show(kind)})}
 city.addEventListener('change',()=>{let value=city.value.trim(),match=citySuggestions().find(x=>x.name===value||x.name.replace(/市$/,'')===value);if(match?.province){province.value=cleanArea(match.province);country.value='中国'}else if(cityAreas[value]){province.value=cityAreas[value];country.value='中国'}});
 city.addEventListener('input',()=>{clearTimeout(timer);let q=city.value.trim();if(q.length<2)return;let token=++request;timer=setTimeout(async()=>{try{let url='https://photon.komoot.io/api/?q='+encodeURIComponent([q,province.value,country.value].filter(Boolean).join(' '))+'&limit=6',res=await fetch(url,{signal:AbortSignal.timeout(6000)}),data=await res.json();if(token!==request||active!=='city'||city.value.trim()!==q)return;let choices=(data.features||[]).filter(x=>x.properties?.name).map(x=>({name:x.properties.name,state:x.properties.state||'',country:x.properties.country||'',lat:x.geometry.coordinates[1],lon:x.geometry.coordinates[0]}));show('city',choices)}catch{}},400)});
 form.addEventListener('click',e=>{if(!e.target.closest('#geoChoices,[name="destination"],[name="country"],[name="province"]'))box.hidden=true});
 loadLocationData().then(()=>{if(!box.hidden)show(active||'country')}).catch(()=>{if(!box.hidden)show(active||'country')});
}
const weatherPresets=['晴','多云','阴','小雨','大雨','雪','雾','大风'];
function setupWeatherPicker(){let input=$('#tripForm')?.elements.weather,box=$('#weatherChoices');if(!input||!box)return;function paint(){box.querySelectorAll('button').forEach(b=>b.classList.toggle('active',input.value.startsWith(b.dataset.weather)))}box.querySelectorAll('button').forEach(b=>b.onclick=()=>{let temp=input.value.match(/-?\d+(?:\.\d+)?\s*°?\s*[C℃]?/i)?.[0]?.replace(/\s/g,'')||'';input.value=b.dataset.weather+(temp?' · '+temp.replace(/(?:°?C|℃)$/i,'')+'℃':'');paint()});input.addEventListener('input',paint);paint()}
function openTrip(id){let t=db.trips.find(x=>x.id===id);openSheet(sheetHead(t?'编辑旅行与旅记':'创建一段新旅行')+`<form id="tripForm"><label class="form-field">旅行名称<input name="name" required maxlength="50" placeholder="例如：京都的秋天" value="${esc(t?.name||'')}"></label><div class="form-row"><label class="form-field">城市 / 目的地<input name="destination" required maxlength="60" autocomplete="off" placeholder="例如：京都" value="${esc(t?.destination||'')}"></label><label class="form-field">国家 / 地区<input name="country" maxlength="60" autocomplete="off" placeholder="例如：中国、日本" value="${esc(t?.country||'')}"></label></div><label class="form-field">省 / 地区（中国地图点亮）<input name="province" maxlength="30" autocomplete="off" placeholder="例如：陕西、浙江、台湾" value="${esc(t?.province||'')}"></label><div class="geo-choices" id="geoChoices" hidden></div><p class="form-note">先选国家、省区，再选城市；列表没有时可直接输入。</p><div class="form-row"><label class="form-field">旅行天数<input name="days" type="number" min="1" max="30" value="${t?.days||3}"></label><label class="form-field">状态<select name="status"><option value="planning" ${t?.status!=='visited'?'selected':''}>计划中</option><option value="visited" ${t?.status==='visited'?'selected':''}>已到访</option></select></label></div><label class="form-field">日期<input name="date" type="month" value="${esc(t?.date||'')}"></label><div class="form-row"><label class="form-field">旅记日期<input name="journalDate" type="date" value="${esc(t?.journalDate||'')}"></label><label class="form-field">当时的天气<input name="weather" maxlength="30" placeholder="晴 · 23℃" value="${esc(t?.weather||'')}"></label></div><div class="weather-choices" id="weatherChoices"><button type="button" data-weather="晴">晴</button><button type="button" data-weather="多云">多云</button><button type="button" data-weather="阴">阴</button><button type="button" data-weather="小雨">小雨</button><button type="button" data-weather="大雨">大雨</button><button type="button" data-weather="雪">雪</button><button type="button" data-weather="雾">雾</button><button type="button" data-weather="大风">大风</button></div><label class="form-field">旅途心情<input name="mood" list="moodOptions" maxlength="30" placeholder="开心、放松、惊喜……" value="${esc(t?.mood||'')}"><datalist id="moodOptions"><option value="开心"><option value="放松"><option value="惊喜"><option value="治愈"><option value="平静"><option value="疲惫但值得"></datalist></label><label class="form-field">旅途故事<textarea name="note" maxlength="700" placeholder="那天的风景、食物和心情……">${esc(t?.note||'')}</textarea></label><label class="upload-label" for="coverFile">＋ ${t?.cover?'更换':'添加'}封面照片<small>照片会压缩后保存在当前设备</small></label><input type="file" id="coverFile" accept="image/*" hidden><label class="upload-label photo-upload" for="cityCoverFile">＋ 上传城市背景图<small>用于旅记分享卡片；不上传可从城市图片库选择</small></label><input type="file" id="cityCoverFile" accept="image/*" hidden>${t?.cityCover?`<div class="form-note">已设置城市背景图</div>`:''}<label class="upload-label photo-upload" for="galleryFiles">＋ 添加旅途照片<small>最多 6 张，保存后在旅记中查看</small></label><input type="file" id="galleryFiles" accept="image/*" multiple hidden>${t?.photos?.length?`<div class="form-note">已保存 ${t.photos.length} 张旅途照片</div>`:''}<p class="form-note">填写国家与城市后，标记“已到访”会计入足迹统计。填写地点后可自动定位地图位置。</p><button class="primary-button" type="submit">${t?'保存旅行':'创建并添加地点'}</button></form>`);setupLocationPicker();setupWeatherPicker();$('#tripForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),wasNew=!t,oldDestination=t?.destination;if(!t){t={id:uid(),places:[],plan:[]};db.trips.unshift(t)}Object.assign(t,{name:String(f.get('name')).trim(),destination:String(f.get('destination')).trim(),country:String(f.get('country')).trim(),days:Math.min(30,Math.max(1,Number(f.get('days'))||3)),status:String(f.get('status')),date:String(f.get('date')),note:String(f.get('note')).trim(),province:String(f.get('province')||'').trim(),journalDate:String(f.get('journalDate')||''),weather:String(f.get('weather')||'').trim(),mood:String(f.get('mood')||'').trim()});if(oldDestination&&oldDestination!==t.destination){t.cityImage='';t.cityImageSource='';t.cityLat=null;t.cityLon=null}if(e.target.dataset.cityLat&&e.target.dataset.cityLon){t.cityLat=Number(e.target.dataset.cityLat);t.cityLon=Number(e.target.dataset.cityLon)}if(isChinaTrip(t))db.mapMode='china';let cityFile=$('#cityCoverFile').files[0];if(cityFile){try{t.cityCover=await compressPhoto(cityFile,1000,.72)}catch{toast('城市背景图处理失败')}}let file=$('#coverFile').files[0];if(file){try{t.cover=await compressPhoto(file)}catch{toast('封面处理失败，其他资料已保存')}}let gallery=[...$('#galleryFiles').files].slice(0,Math.max(0,6-(t.photos?.length||0)));t.photos=t.photos||[];if(t.journalHidden&&(t.note||file||gallery.length))t.journalHidden=false;for(let photo of gallery){try{t.photos.push(await compressPhoto(photo,640,.64))}catch{}}persist();closeSheet();activeTripId=t.id;if(wasNew){go('plans');setTimeout(()=>$('#plannerDetail').scrollIntoView({behavior:'smooth',block:'start'}),30);locateTrip(t)}else{render();locateTrip(t)}toast(wasNew?'旅行已创建':'旅行已保存')};}
function compressPhoto(file,max=800,quality=.7){return new Promise((resolve,reject)=>{let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let ratio=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=()=>{URL.revokeObjectURL(url);reject()};img.src=url})}
async function locateTrip(t){if(t.cityLat!=null&&t.cityLon!=null)return;try{let r=await fetch('https://photon.komoot.io/api/?q='+encodeURIComponent([t.destination,t.country].filter(Boolean).join(' '))+'&limit=1',{signal:AbortSignal.timeout(8000)});let d=await r.json(),h=d.features?.[0];if(h){t.cityLon=h.geometry.coordinates[0];t.cityLat=h.geometry.coordinates[1];if(!t.province)t.province=cleanArea(h.properties?.state||'');if(!t.country)t.country=h.properties?.country||'';persist()}}catch{}}
function openPlace(id){let t=current();if(!t)return;let p=t.places.find(x=>x.id===id);openSheet(sheetHead(p?'编辑地点':'添加心动地点')+`<form id="placeForm"><label class="form-field">地点名称<input name="name" required maxlength="100" placeholder="例如：清水寺" value="${esc(p?.name||'')}"></label><div class="form-row"><label class="form-field">类型<select name="category">${['景点','自然','美食','购物','住宿','其他'].map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="form-field">停留分钟<input name="duration" type="number" min="15" max="600" value="${p?.duration||90}"></label></div><label class="form-field">备注<input name="note" maxlength="200" placeholder="想去的理由、预约提醒……" value="${esc(p?.note||'')}"></label><div class="form-row"><label class="form-field">纬度（可选）<input name="lat" type="number" step="any" placeholder="自动查找" value="${p?.lat??''}"></label><label class="form-field">经度（可选）<input name="lon" type="number" step="any" placeholder="自动查找" value="${p?.lon??''}"></label></div><p class="form-note">保存后会尝试在线定位，找不到时可以手动填写坐标。</p><button class="primary-button">保存地点</button></form>`);$('#placeForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);if(!p){p={id:uid()};t.places.push(p)}Object.assign(p,{name:String(f.get('name')).trim(),category:String(f.get('category')),duration:Number(f.get('duration'))||90,note:String(f.get('note')).trim(),lat:f.get('lat')===''?null:Number(f.get('lat')),lon:f.get('lon')===''?null:Number(f.get('lon'))});t.plan=[];persist();closeSheet();toast('地点已保存');if(!validCoord(p))locatePlace(p,t)}}
async function locatePlace(p,t){try{let r=await fetch('https://photon.komoot.io/api/?q='+encodeURIComponent(p.name+' '+t.destination+' '+t.country)+'&limit=1',{signal:AbortSignal.timeout(9000)}),d=await r.json(),h=d.features?.[0];if(!h)throw Error();p.lon=h.geometry.coordinates[0];p.lat=h.geometry.coordinates[1];p.address=[h.properties?.name,h.properties?.city,h.properties?.country].filter(Boolean).join(' · ');persist()}catch{toast(`${p.name} 没有自动定位，可手动补坐标`)}}
function validCoord(p){return p&&p.lat!=null&&p.lon!=null&&p.lat!==''&&p.lon!==''&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))&&Math.abs(Number(p.lat))<=90&&Math.abs(Number(p.lon))<=180}
function openImport(){if(!current())return;openSheet(sheetHead('导入想去的地方')+`<label class="upload-label" for="placesFile">⇧ 上传地点清单或截图<small>支持 TXT、CSV、JSON、图片截图</small></label><input type="file" id="placesFile" accept=".txt,.csv,.json,image/*" hidden><label class="form-field">或直接粘贴<textarea id="importText" placeholder="清水寺\n伏见稻荷大社\n锦市场"></textarea></label><p class="form-note">每行一个地点；CSV 可包含 name、lat、lon、note。截图会在本机识别文字，请先检查识别结果。</p><button class="primary-button" id="importSubmit">导入并定位</button>`);$('#placesFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.type.startsWith('image/')){toast('正在识别截图…');$('#importText').value=(await recognizeImage(f)).split(/\r?\n/).map(x=>x.trim()).filter(x=>x.length>1).join('\n');toast('识别完成，请检查地点名称')}else{$('#importText').value=await f.text();toast('文件已读取')}}catch{toast('识别失败，请手动粘贴地点')}};$('#importSubmit').onclick=commitImport}
async function recognizeImage(file){if('TextDetector'in window){try{let b=await createImageBitmap(file),a=await new TextDetector().detect(b);b.close();if(a.length)return a.map(x=>x.rawValue).join('\n')}catch{}}if(!window.Tesseract)await new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});let w=await Tesseract.createWorker(['chi_sim','eng']);try{return(await w.recognize(file)).data.text||''}finally{await w.terminate()}}
function parseInput(text){let s=text.trim();if(!s)return[];if(s[0]==='['||s[0]==='{'){let o=JSON.parse(s),a=Array.isArray(o)?o:o.places||[];return a.map(x=>typeof x==='string'?{name:x}:{name:x.name||x.地点||x.title,lat:x.lat??x.纬度,lon:x.lon??x.lng??x.经度,note:x.note||x.备注,category:x.category||x.类型})}let lines=s.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),header=null;return lines.flatMap((line,i)=>{let parts=line.includes('\t')?line.split('\t'):line.split(',');if(i===0&&/^(name|地点|名称|place)/i.test(parts[0])){header=parts.map(x=>x.trim().toLowerCase());return[]}if(header){let o={};parts.forEach((v,j)=>o[header[j]]=v.trim());return[{name:o.name||o.地点||o.名称||o.place,lat:o.lat||o.纬度,lon:o.lon||o.lng||o.经度,note:o.note||o.备注,category:o.category||o.类型}]}return[{name:parts[0],lat:parts[1],lon:parts[2]}]})}
async function commitImport(){let t=current(),rows;try{rows=parseInput($('#importText').value)}catch{toast('清单格式无法识别');return}rows=rows.filter(x=>x.name&&String(x.name).trim());let unique=rows.filter(x=>!t.places.some(p=>p.name.toLowerCase()===String(x.name).trim().toLowerCase()));if(!unique.length){toast('没有新地点，请检查清单');return}let created=unique.map(x=>({id:uid(),name:String(x.name).trim(),lat:x.lat==null||x.lat===''?null:Number(x.lat),lon:x.lon==null||x.lon===''?null:Number(x.lon),note:String(x.note||''),category:String(x.category||'景点'),duration:90}));t.places.push(...created);t.plan=[];persist();closeSheet();toast(`已加入 ${created.length} 个地点，正在定位`);for(let p of created.filter(x=>!validCoord(x)))await locatePlace(p,t)}
function km(a,b){let R=6371,dLat=(Number(b.lat)-Number(a.lat))*Math.PI/180,dLon=(Number(b.lon)-Number(a.lon))*Math.PI/180,x=Math.sin(dLat/2)**2+Math.cos(Number(a.lat)*Math.PI/180)*Math.cos(Number(b.lat)*Math.PI/180)*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function routeDistance(a){return a.slice(1).reduce((n,p,i)=>n+km(a[i],p),0)}
function optimizeDay(points){if(points.length<3)return points;let best=points.slice(),bestD=routeDistance(best),changed=true,passes=0;while(changed&&passes++<12){changed=false;for(let i=0;i<best.length-1;i++)for(let j=i+1;j<best.length;j++){let cand=best.slice(0,i).concat(best.slice(i,j+1).reverse(),best.slice(j+1)),d=routeDistance(cand);if(d+1e-7<bestD){best=cand;bestD=d;changed=true}}}return best}
function buildPlan(places,days){let count=Math.min(days,places.length),groups=Array.from({length:days},()=>[]);if(!count)return groups;let center={lat:places.reduce((n,p)=>n+Number(p.lat),0)/places.length,lon:places.reduce((n,p)=>n+Number(p.lon),0)/places.length},seeds=[places.reduce((a,b)=>km(a,center)>km(b,center)?a:b)];while(seeds.length<count){let left=places.filter(p=>!seeds.includes(p));seeds.push(left.reduce((a,b)=>Math.min(...seeds.map(x=>km(a,x)))>Math.min(...seeds.map(x=>km(b,x)))?a:b))}let sizes=Array.from({length:count},(_,i)=>Math.floor(places.length/count)+(i<places.length%count?1:0));seeds.forEach((p,i)=>groups[i].push(p));let remaining=places.filter(p=>!seeds.includes(p));remaining.sort((a,b)=>{let da=seeds.map(x=>km(a,x)).sort((x,y)=>x-y),db=seeds.map(x=>km(b,x)).sort((x,y)=>x-y);return(db[1]??db[0])-db[0]-((da[1]??da[0])-da[0])});for(let p of remaining){let best=-1,cost=Infinity;for(let i=0;i<count;i++){if(groups[i].length>=sizes[i])continue;let c=Math.min(...groups[i].map(x=>km(p,x)));if(c<cost){cost=c;best=i}}groups[best].push(p)}return groups.map(optimizeDay)}
function generate(){let t=current(),located=t.places.filter(validCoord),missing=t.places.length-located.length;if(!located.length){toast('先添加并定位地点');return}t.plan=buildPlan(located,t.days);activeDay=0;persist();toast(`路线已生成${missing?'，'+missing+' 个地点待定位':''}`);setTimeout(()=>$('#routePanel')?.scrollIntoView({behavior:'smooth',block:'start'}),20)}
function moveStop(id,dir){let t=current(),arr=t?.plan?.[activeDay];if(!arr)return;let i=arr.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];persist()}
function openMaps(id){let t=current(),p=t?.places.find(x=>x.id===id);if(!p)return;window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(validCoord(p)?p.lat+','+p.lon:p.name+' '+t.destination),'_blank','noopener')}
function deletePlace(id){let t=current();if(!t)return;t.places=t.places.filter(x=>x.id!==id);t.plan=[];persist();toast('地点已移除')}
function share(){let n=numbers(),text=`我的旅行足迹：${n.countries} 个国家 / 地区，${n.cities} 座城市，${n.memories} 篇旅记。`;if(navigator.share)navigator.share({title:'绮途 · 我的旅行足迹',text,url:location.href}).catch(()=>{});else navigator.clipboard?.writeText(text+' '+location.href).then(()=>toast('分享文字和链接已复制')).catch(()=>toast(text))}
function exportData(){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.href=url;a.download='绮途-旅行备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('旅行备份已下载')}
async function importBackup(e){let f=e.target.files[0];if(!f)return;try{let o=JSON.parse(await f.text());if(!Array.isArray(o.trips))throw Error();db={trips:o.trips,saved:Array.isArray(o.saved)?o.saved:[],profile:o.profile||{name:'旅行收藏家',avatar:''},mapMode:o.mapMode||'world'};for(let t of db.trips){t.places=Array.isArray(t.places)?t.places:[];t.plan=Array.isArray(t.plan)?t.plan:[];t.status=t.status||'planning';t.country=t.country||'';t.note=t.note||'';t.province=t.province||'';t.photos=Array.isArray(t.photos)?t.photos:[]}activeTripId=null;persist();go('home');toast('旅行备份已导入')}catch{toast('备份文件格式不正确')}}



function openPlanMenu(id){let t=db.trips.find(x=>x.id===id);if(!t)return;openSheet(sheetHead('管理这段旅行')+`<div class="menu-trip"><span class="plan-glyph">✧</span><div><strong>${esc(t.name)}</strong><small>${esc(t.destination)} · ${t.days} 天</small></div></div><div class="plan-menu"><button id="menuEdit">✎ <span>编辑旅行与旅记</span><b>↗</b></button><button id="menuDuplicate">▣ <span>复制这份计划</span><b>↗</b></button><button class="danger" id="menuDelete">× <span>删除这段旅行</span><b>↗</b></button></div>`);$('#menuEdit').onclick=()=>openTrip(t.id);$('#menuDuplicate').onclick=()=>duplicateTrip(t);$('#menuDelete').onclick=()=>confirmDeleteTrip(t)}
function duplicateTrip(t){let copy=JSON.parse(JSON.stringify(t));copy.id=uid();copy.name=t.name+' · 副本';copy.status='planning';copy.photos=[];db.trips.unshift(copy);activeTripId=copy.id;persist();closeSheet();go('plans');toast('已复制计划，可继续编辑')}
function confirmDeleteTrip(t){openSheet(sheetHead('删除旅行？')+`<p class="form-note">「${esc(t.name)}」的地点、路线和旅记会从这台设备移除。删除后可立即撤销。</p><div class="inline-actions"><button class="primary-button secondary" id="cancelDelete">先保留</button><button class="primary-button danger-button" id="confirmDelete">删除旅行</button></div>`);$('#cancelDelete').onclick=closeSheet;$('#confirmDelete').onclick=()=>{let index=db.trips.findIndex(x=>x.id===t.id);if(index<0)return;lastDeleted={trip:db.trips[index],index};db.trips.splice(index,1);if(activeTripId===t.id)activeTripId=null;persist();closeSheet();go('plans');showUndoToast()}}
function showUndoToast(){let e=$('#toast');e.innerHTML='旅行已删除 <button id="undoDeleteButton">撤销</button>';e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{e.classList.remove('show');lastDeleted=null},10000);$('#undoDeleteButton').onclick=()=>{if(!lastDeleted)return;db.trips.splice(lastDeleted.index,0,lastDeleted.trip);activeTripId=lastDeleted.trip.id;lastDeleted=null;persist();e.classList.remove('show');toast('已恢复旅行')}}
let lastDeletedJournal=null;
function confirmDeleteJournal(id){let t=db.trips.find(x=>x.id===id);if(!t)return;openSheet(sheetHead('删除这篇旅记？')+`<p class="form-note">将移除「${esc(t.name)}」的心得、封面和旅途照片。旅行计划、地点和足迹会保留。</p><div class="inline-actions"><button class="primary-button secondary" id="keepJournal">先保留</button><button class="primary-button danger-button" id="deleteJournalNow">删除旅记</button></div>`);$('#keepJournal').onclick=closeSheet;$('#deleteJournalNow').onclick=()=>{lastDeletedJournal={id:t.id,note:t.note,cover:t.cover,photos:[...(t.photos||[])],hidden:t.journalHidden};t.note='';t.cover='';t.photos=[];t.journalHidden=true;persist();closeSheet();go('memories');let e=$('#toast');e.innerHTML='旅记已删除，计划仍在 <button id="undoJournalButton">撤销</button>';e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{e.classList.remove('show');lastDeletedJournal=null},10000);$('#undoJournalButton').onclick=()=>{let saved=lastDeletedJournal,trip=db.trips.find(x=>x.id===saved?.id);if(!trip)return;Object.assign(trip,{note:saved.note,cover:saved.cover,photos:saved.photos,journalHidden:saved.hidden});lastDeletedJournal=null;persist();toast('旅记已恢复')}}}
function openJourney(t){openSheet(sheetHead(t.name)+`<div class="journey-detail"><div class="journey-cover ${t.cover?'covered':''}" ${t.cover?`style="background-image:url('${esc(t.cover)}')"`:''}><span>${esc(t.destination)}</span></div><div class="journey-copy"><span class="eyebrow">${esc(t.country||'旅行记录')} · ${esc(t.journalDate||t.date||'旅途日记')}</span><div class="journey-tags">${t.weather?`<span>☀ ${esc(t.weather)}</span>`:''}${t.mood?`<span>♡ ${esc(t.mood)}</span>`:''}</div><p>${esc(t.note||'这段旅程还没有写下心得。')}</p></div>${t.photos?.length?`<div class="photo-strip">${t.photos.map((p,i)=>`<button data-photo="${esc(t.id)}" data-photo-index="${i}"><img src="${esc(p)}" alt="旅途照片 ${i+1}"></button>`).join('')}</div>`:''}<div class="inline-actions"><button class="primary-button" data-edit-trip="${esc(t.id)}">编辑心得与照片</button><button class="primary-button secondary" data-plan-trip="${esc(t.id)}">查看行程</button></div><button class="primary-button share-journey-button" data-share-trip="${esc(t.id)}">↗ 分享这篇旅记</button><button class="remove-photo" data-delete-journal="${esc(t.id)}">删除这篇旅记</button></div>`)}


let cropState=null;
function drawAvatarCrop(){if(!cropState)return;let {img,zoom,panX,panY}=cropState,canvas=$('#cropCanvas');if(!canvas)return;let ctx=canvas.getContext('2d'),size=canvas.width,scale=Math.max(size/img.width,size/img.height)*zoom,w=img.width*scale,h=img.height*scale;cropState.panX=Math.max((size-w)/2,Math.min((w-size)/2,panX));cropState.panY=Math.max((size-h)/2,Math.min((h-size)/2,panY));ctx.clearRect(0,0,size,size);ctx.drawImage(img,(size-w)/2+cropState.panX,(size-h)/2+cropState.panY,w,h)}
function openProfile(){cropState=null;openSheet(sheetHead('编辑个人资料')+`<form id="profileForm"><div class="avatar-preview">${db.profile.avatar?`<img src="${esc(db.profile.avatar)}" alt="当前头像">`:'✦'}</div><label class="upload-label" for="avatarFile">选择头像照片<small>选择后可拖动位置、缩放裁剪</small></label>${db.profile.avatar?`<button type="button" class="crop-reset current-crop" id="recropAvatar">重新调整当前头像</button>`:''}<input type="file" id="avatarFile" accept="image/*" hidden><div class="crop-panel" id="cropPanel" hidden><div class="crop-stage"><canvas id="cropCanvas" width="320" height="320" aria-label="拖动图片调整头像位置"></canvas><span class="crop-mask"></span></div><div class="crop-controls"><span>缩小</span><input id="cropZoom" type="range" min="1" max="3" step="0.01" value="1" aria-label="头像缩放"><span>放大</span></div><button type="button" class="crop-reset" id="cropReset">恢复居中</button><p class="form-note">拖动照片调整位置，滑动刻度调整大小。圆形范围就是最终头像。</p></div><label class="form-field">昵称<input name="name" required maxlength="24" value="${esc(db.profile.name||'旅行收藏家')}"></label><button class="primary-button">保存个人资料</button></form>`);let recrop=$('#recropAvatar');if(recrop)recrop.onclick=()=>{let img=new Image();img.onload=()=>{cropState={img,zoom:1,panX:0,panY:0};$('#cropPanel').hidden=false;$('.avatar-preview').classList.add('is-hidden');drawAvatarCrop()};img.src=db.profile.avatar};$('#avatarFile').onchange=e=>{let f=e.target.files[0];if(!f)return;let img=new Image(),url=URL.createObjectURL(f);img.onload=()=>{URL.revokeObjectURL(url);cropState={img,zoom:1,panX:0,panY:0};$('#cropPanel').hidden=false;$('.avatar-preview').classList.add('is-hidden');drawAvatarCrop()};img.onerror=()=>{URL.revokeObjectURL(url);toast('头像读取失败')};img.src=url};$('#cropZoom').oninput=e=>{if(!cropState)return;cropState.zoom=Number(e.target.value);drawAvatarCrop()};$('#cropReset').onclick=()=>{if(!cropState)return;cropState.zoom=1;cropState.panX=0;cropState.panY=0;$('#cropZoom').value='1';drawAvatarCrop()};let canvas=$('#cropCanvas'),origin=null;canvas.onpointerdown=e=>{if(!cropState)return;origin={x:e.clientX,y:e.clientY,panX:cropState.panX,panY:cropState.panY};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!origin||!cropState)return;let ratio=canvas.width/canvas.getBoundingClientRect().width;cropState.panX=origin.panX+(e.clientX-origin.x)*ratio;cropState.panY=origin.panY+(e.clientY-origin.y)*ratio;drawAvatarCrop()};canvas.onpointerup=canvas.onpointercancel=()=>origin=null;$('#profileForm').onsubmit=e=>{e.preventDefault();db.profile.name=String(new FormData(e.target).get('name')).trim();if(cropState)db.profile.avatar=canvas.toDataURL('image/jpeg',.82);cropState=null;persist();closeSheet();toast('头像与昵称已更新')}}
function openPhoto(t,i){let photo=t.photos[i];openSheet(sheetHead(`${t.destination} · 照片 ${i+1}/${t.photos.length}`)+`<img class="photo-viewer" src="${esc(photo)}" alt="旅途照片"><div class="inline-actions"><button class="primary-button" id="prevPhoto">上一张</button><button class="primary-button" id="nextPhoto">下一张</button></div><button class="remove-photo" id="removePhoto">移除这张照片</button>`);$('#prevPhoto').onclick=()=>openPhoto(t,(i-1+t.photos.length)%t.photos.length);$('#nextPhoto').onclick=()=>openPhoto(t,(i+1)%t.photos.length);$('#removePhoto').onclick=()=>{t.photos.splice(i,1);persist();closeSheet();toast('照片已移除')}}

function searchTrips(){openSheet(sheetHead('搜索我的旅行')+`<label class="form-field">目的地或旅行名称<input id="searchInput" placeholder="输入城市、国家或旅行名称" autofocus></label><div id="searchResults"></div>`);let input=$('#searchInput');input.oninput=()=>{let q=input.value.trim().toLowerCase();$('#searchResults').innerHTML=q?db.trips.filter(t=>(t.name+' '+t.destination+' '+t.country).toLowerCase().includes(q)).map(t=>`<button class="plan-card" style="width:100%;border:0;text-align:left" data-trip="${esc(t.id)}"><span class="plan-glyph">✧</span><span class="plan-info"><strong>${esc(t.name)}</strong><small>${esc(t.destination)} · ${esc(t.country)}</small></span><b>›</b></button>`).join('')||'<p class="form-note">没有找到匹配的旅行</p>':'<p class="form-note">只搜索你在这台设备上保存的旅行。</p>'};input.dispatchEvent(new Event('input'));input.focus()}
function markVisited(id){let t=db.trips.find(x=>x.id===id);if(!t)return;t.status=t.status==='visited'?'planning':'visited';persist();if(t.status==='visited')locateTrip(t);toast(t.status==='visited'?'已点亮这段旅行':'已改回计划中')}
async function shrinkShareImage(src,max=440,quality=.55){
 if(!src||!src.startsWith('data:image/'))return '';
 return new Promise(resolve=>{let im=new Image();im.onload=()=>{let scale=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight));let cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(im.naturalWidth*scale));cv.height=Math.max(1,Math.round(im.naturalHeight*scale));cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);resolve(cv.toDataURL('image/jpeg',quality))};im.onerror=()=>resolve('');im.src=src})
}
function shareBytesToUrl(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function sharePayload(t){
 let photos=[t.cover,...(t.photos||[])].filter(Boolean),small=[];
 for(let p of photos.slice(0,3)){let result=await shrinkShareImage(p,small.length?180:320,small.length?.36:.46);if(result)small.push(result)}
 let cityCover=await shrinkShareImage(t.cityCover||'',360,.42);
 let base={v:1,name:t.name,destination:t.destination,country:t.country,province:t.province,date:t.journalDate||t.date,weather:t.weather||'',mood:t.mood||'',note:t.note||'',lat:t.cityLat,lon:t.cityLon,cityImage:t.cityImage||'',cityImageSource:t.cityImageSource||''};
 async function encode(){let bytes=new TextEncoder().encode(JSON.stringify({...base,cityCover,photos:small}));if('CompressionStream' in window){let stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));bytes=new Uint8Array(await new Response(stream).arrayBuffer());return 'g'+shareBytesToUrl(bytes)}return 'j'+shareBytesToUrl(bytes)}
 let encoded=await encode();while(encoded.length>18000&&small.length>1){small.pop();encoded=await encode()}if(encoded.length>18000&&cityCover){cityCover='';encoded=await encode()}if(encoded.length>18000&&small.length){small[0]=await shrinkShareImage(small[0],190,.29);encoded=await encode()}
 return {url:new URL('./share.html#'+encoded,location.href).href,photos:small.length,limited:encoded.length>18000};
}
async function findCityImage(id){let t=db.trips.find(x=>x.id===id);if(!t)return;let button=$('#findCityPhoto');if(button){button.disabled=true;button.textContent='正在查找城市照片…'}try{let title=encodeURIComponent(t.destination||''),url=`https://zh.wikipedia.org/w/api.php?action=query&format=json&prop=pageimages&titles=${title}&pithumbsize=1200&piplicense=free&origin=*`,r=await fetch(url),j=await r.json(),item=Object.values(j.query?.pages||{})[0];if(!item?.thumbnail?.source)throw Error();t.cityImage=item.thumbnail.source;t.cityImageSource='https://zh.wikipedia.org/wiki/'+title;persist();openSharePreview(id);toast('已选取城市图片')}catch{toast('暂时没找到城市照片，可自行上传背景图');if(button){button.disabled=false;button.textContent='寻找城市代表照片'}}}
async function openSharePreview(id){let t=db.trips.find(x=>x.id===id);if(!t)return;let city=t.cityCover||t.cityImage||t.cover||'',photo=t.cover||t.photos?.[0]||'';openSheet(sheetHead('分享这篇旅记')+`<div class="share-intro">这张卡片只包含「${esc(t.name)}」。确认内容后再生成专属链接。</div><div class="share-preview"><div class="share-scene" ${city?`style="background-image:url('${esc(city)}')"`:''}><div class="share-scene-shade"></div><div class="share-scene-top">绮途 · TRAVEL JOURNAL</div><div class="share-scene-title"><small>${esc([t.country,t.province].filter(Boolean).join(' · '))}</small><h3>${esc(t.destination||t.name)}</h3></div>${photo?`<div class="share-inset"><img src="${esc(photo)}" alt="旅途记录照片"></div>`:''}</div><div class="share-preview-body"><small>${esc(t.journalDate||t.date||'未填写日期')}${t.weather?' · '+esc(t.weather):''}${t.mood?' · '+esc(t.mood):''}</small><h3>${esc(t.name)}</h3><p>${esc(t.note||'这段旅程还没有写下心得。')}</p></div></div>${t.cityImageSource?`<a class="share-credit" href="${esc(t.cityImageSource)}" target="_blank" rel="noopener">城市照片来源：维基百科 ↗</a>`:''}<div class="share-actions"><button class="primary-button secondary" id="findCityPhoto">寻找城市代表照片</button><button class="primary-button" id="createJourneyLink">生成并分享专属链接</button></div><p class="form-note">链接会包含这篇旅记的压缩预览图。收到链接的人能看到地点、日期、天气、心情和文字；不会看到其他旅记或你的个人资料。</p>`);$('#findCityPhoto').onclick=()=>findCityImage(id);$('#createJourneyLink').onclick=async e=>{let b=e.currentTarget;b.disabled=true;b.textContent='正在准备分享链接…';try{let result=await sharePayload(t);if(result.limited)toast('图片较大，链接可能在部分聊天软件中无法打开');let copied=false;if(navigator.share){try{await navigator.share({title:t.name,text:`${t.destination} · ${t.name}`,url:result.url});copied=true}catch(err){if(err.name==='AbortError'){b.disabled=false;b.textContent='生成并分享专属链接';return}}}if(!copied){try{await navigator.clipboard.writeText(result.url);copied=true}catch{let input=document.createElement('textarea');input.value=result.url;document.body.append(input);input.select();copied=document.execCommand('copy');input.remove()}}b.disabled=false;b.textContent=copied?'已分享 / 已复制链接':'再次尝试复制链接';toast(copied?`专属链接已准备好，包含 ${result.photos} 张预览照片`:'复制失败，请在系统浏览器重试')}catch{b.disabled=false;b.textContent='重新生成链接';toast('生成失败，请减少照片后重试')}}}

document.addEventListener('pointerdown',e=>{let b=e.target.closest('button');if(!b||!b.matches('.new-plan,.primary-button,.map-bottom button,.map-switch button')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let r=b.getBoundingClientRect(),dot=document.createElement('span');dot.className='tap-ripple';dot.style.left=e.clientX-r.left+'px';dot.style.top=e.clientY-r.top+'px';b.appendChild(dot);setTimeout(()=>dot.remove(),430)});document.addEventListener('click',e=>{let id=e.target.closest('button')?.id||e.target.id;let el=e.target.closest('[data-go],[data-close],[data-trip],[data-plan-trip],[data-edit-trip],[data-status],[data-edit-place],[data-delete-place],[data-move],[data-map-place],[data-day],[data-photo],[data-plan-menu],[data-delete-journal],[data-map-cluster],[data-share-trip]');if(el){if(el.dataset.shareTrip)openSharePreview(el.dataset.shareTrip);else if(el.dataset.mapCluster!=null)openMapCluster(el.dataset.mapCluster);else if(el.dataset.planMenu)openPlanMenu(el.dataset.planMenu);else if(el.dataset.deleteJournal)confirmDeleteJournal(el.dataset.deleteJournal);else if(el.dataset.go)go(el.dataset.go);else if(el.hasAttribute('data-close'))closeSheet();else if(el.dataset.trip){let t=db.trips.find(x=>x.id===el.dataset.trip);closeSheet();if(t){activeTripId=t.id;t.status==='visited'?go('memories'):go('plans');if(t.status==='visited')openJourney(t)}}else if(el.dataset.planTrip){closeSheet();activeTripId=el.dataset.planTrip;activeDay=0;go('plans');setTimeout(()=>$('#plannerDetail').scrollIntoView({behavior:'smooth',block:'start'}),20)}else if(el.dataset.editTrip)openTrip(el.dataset.editTrip);else if(el.dataset.status)markVisited(el.dataset.status);else if(el.dataset.editPlace)openPlace(el.dataset.editPlace);else if(el.dataset.deletePlace)deletePlace(el.dataset.deletePlace);else if(el.dataset.move)moveStop(el.dataset.move,Number(el.dataset.dir));else if(el.dataset.mapPlace)openMaps(el.dataset.mapPlace);else if(el.dataset.day!=null){activeDay=Number(el.dataset.day);renderPlannerDetail()}else if(el.dataset.photo){let t=db.trips.find(x=>x.id===el.dataset.photo);let i=Number(el.dataset.photoIndex);if(t?.photos?.[i])openPhoto(t,i)}return}if(e.target===$('#modal'))closeSheet();let region=e.target.closest?.('#mapSvg [data-area],#mapSvg [data-code]');if(region){openMapArea(region);return}let modeButton=e.target.closest?.('[data-map-mode]');if(modeButton){db.mapMode=modeButton.dataset.mapMode;persist();return}if(id==='newTripButton'||id==='mapAddButton'||id==='firstMemoryButton')openTrip();else if(id==='searchButton')searchTrips();else if(id==='editProfileButton'||id==='headerAvatarButton')openProfile();else if(id==='themeButton')toggleTheme();else if(id==='shareMapButton'||id==='shareProfileButton')share();else if(id==='exportButton')exportData();else if(id==='importPlacesButton')openImport();else if(id==='addPlaceButton')openPlace();else if(id==='generateButton')generate();else if(id==='memAll'){memoryFilter='all';renderMemories()}else if(id==='memVisited'){memoryFilter='visited';renderMemories()}else if(id==='memUpcoming'){memoryFilter='upcoming';renderMemories()}});
window.addEventListener('resize',()=>{let svg=$('#mapSvg svg');if(svg)placeMapPins(svg,db.mapMode)});$('#backupFile').onchange=importBackup;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden)closeSheet()});applyTheme();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
